
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"CoolDiamonds2AM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
	
		    var tmpMess=k.data.split("#");
			

		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.ntc.bdg!=undefined){
			
			if(gameController.lbv!=parseInt(tmpMess[1])){
				
			gameController.lbv=parseInt(tmpMess[1]);	
			gameController.ntc.bdg.cli("creditd", "#weq", [gameController.ztg(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
